heroArtwork.src='banaras-boat-lit.png';heroArtwork.alt='Dhiraj and Neha seen from behind in a boat surrounded by floating diyas on the Ganga';
let boatComplete=false,boatStarted=false;const revealTimer=new MutationObserver(()=>{if(entry.classList.contains('names-ready')&&!boatComplete){entry.classList.remove('names-ready');entry.classList.add('boat-ready');entry.querySelector('.boat-light-control').focus()}});revealTimer.observe(entry,{attributes:true,attributeFilter:['class']});
const boatLight=document.createElement('button');boatLight.className='boat-light-control';boatLight.textContent='Tap to light the floating diyas';entry.append(boatLight);
[[25,12,0],[72,13,.6],[50,23,1.2],[80,26,1.7]].forEach(([x,y,d])=>{const burst=document.createElement('div');burst.className='boat-burst';burst.style.cssText=`--x:${x}%;--y:${y}%;--delay:${d}s`;burst.innerHTML='<img src="golden-firework.svg" alt="">';entry.append(burst)});
boatLight.onclick=()=>{if(boatStarted)return;boatStarted=true;entry.classList.add('boat-lit');setTimeout(()=>entry.classList.add('boat-celebrating'),motion?50:6200);setTimeout(()=>{boatComplete=true;entry.classList.add('names-ready');entry.querySelector('.banaras-continue').focus()},motion?100:10500)};
